import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { Text } from 'react-native'

interface SettingsSectionTitleProps {
	title: string
}

export const SettingsSectionTitle = ({ title }: SettingsSectionTitleProps) => {
	const { theme } = useTheme()
	return <Text style={styles.title(theme)}>{title}</Text>
}

const styles = defineStyles({
	title: (theme: Theme) => ({
		fontSize: 18,
		fontWeight: '500',
		color: colors[theme].gray[900],
		marginBottom: 8
	})
})
